/**
 * Shared mutable state for the plugin-runner permission-staging test.
 * Stub modules generated by registerHooks import this file by file URL so the
 * test and the runner observe the same FakeTransport instance.
 */
import { createConnection } from 'node:net'

export const state = {
  transport: null,
  notifications: [],
  setCalls: [],
  spawnCalls: [],
  failSpawn: false,
}

export class FakeTransport {
  constructor() {
    state.transport = this
  }
  onRequest(fn) {
    this.handler = fn
  }
  notify(method, params) {
    state.notifications.push({ method, params })
  }
  start() {}
  flush() {}
  close() {}
}

function fakePipe() {
  const listeners = { error: [] }
  return {
    listeners,
    on(event, fn) {
      ;(listeners[event] ??= []).push(fn)
      return this
    },
    write() {
      return true
    },
  }
}

function makeFakeChild() {
  const listeners = new Map()
  return {
    stdio: [null, null, null, fakePipe(), fakePipe()],
    exitCode: null,
    signalCode: null,
    on(event, fn) {
      const entries = listeners.get(event) ?? []
      entries.push({ fn, once: false })
      listeners.set(event, entries)
      return this
    },
    once(event, fn) {
      const entries = listeners.get(event) ?? []
      entries.push({ fn, once: true })
      listeners.set(event, entries)
      return this
    },
    off(event, fn) {
      listeners.set(event, (listeners.get(event) ?? []).filter((entry) => entry.fn !== fn))
      return this
    },
    emit(event, ...args) {
      const entries = listeners.get(event) ?? []
      listeners.set(event, entries.filter((entry) => !entry.once))
      for (const entry of entries) entry.fn(...args)
    },
    kill() {},
  }
}

export let fakeChild = makeFakeChild()

export function spawnTui(bin, args, options) {
  fakeChild = makeFakeChild()
  state.spawnCalls.push({ bin, args, options })
  if (state.failSpawn) {
    state.failSpawn = false
    queueMicrotask(() => fakeChild.emit('error', new Error('simulated launch failure')))
    return fakeChild
  }
  const attachTcp = args.indexOf('--attach-tcp')
  if (attachTcp >= 0) {
    const [host, port] = args[attachTcp + 1].split(':')
    const socket = createConnection({ host, port: Number(port) }, () => {
      socket.end(`${options.env.DSH_TUI_ATTACH_TOKEN}\n`)
    })
    socket.on('error', () => {})
  }
  return fakeChild
}
